package com.sigtm.backend.model;
import jakarta.persistence.*; import jakarta.validation.constraints.Min; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="inspecciones_recepcion_compra") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class InspeccionRecepcionCompra { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="recepcion_id",nullable=false) private RecepcionCompra receipt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="producto_id",nullable=false) private Producto product; @NotBlank @Column(nullable=false,length=20) private String result; @NotNull @Min(0) @Column(nullable=false) private Integer acceptedQuantity; @NotNull @Min(0) @Column(nullable=false) private Integer rejectedQuantity; @Column(nullable=false) private LocalDateTime inspectedAt; @Column(length=500) private String observations; }
